// ============================================================
// Agentverse identity + metadata.
//
// The Agentverse agent URI/address is generated by Agentverse when
// you register the agent (Launch an Agent -> Connect Agent -> Chat
// Protocol). The generated AGENT_URI is stored in env and is the
// stable handle that makes the agent discoverable/reachable.
//
// AGENT_SEED_PHRASE is the stable seed associated with the agent
// identity when the official SDK derives the address. It is kept here
// only as configuration metadata; it is never logged or exposed.
//
// SECURITY:
//   - The seed phrase is read from env and is NEVER surfaced in logs,
//     responses, or requests.
//   - AGENT_URI has no secret material but we still avoid logging it
//     unless explicitly requested.
// ============================================================

const { env } = require('../config/env')

const AGENT_NAME = 'CrisisFlow'

const AGENT_DESCRIPTION =
  'CrisisFlow is an AI-powered emergency healthcare coordination agent that helps users discover nearby healthcare facilities, pharmacies, blood banks, and emergency services and calculate routes using real-world location data.'

// Capabilities currently supported and exposed for discovery.
const CAPABILITIES = [
  'find_emergency_facility',
  'find_healthcare_service',
  'find_pharmacy',
  'find_blood_bank',
  'calculate_route',
  'find_emergency_facility_and_route',
]

// Discovery keywords that accurately describe what the agent actually does.
const KEYWORDS = [
  'emergency healthcare',
  'hospital finder',
  'healthcare facilities',
  'emergency facility',
  'pharmacy finder',
  'blood bank finder',
  'healthcare coordination',
  'emergency route',
  'medical facility navigation',
]

// The Agentverse-assigned URI/address, if configured. Empty until the
// agent is registered (Agentverse generates this).
function agentUri() {
  return env.agentUri || ''
}

function isConfigured() {
  // A URI is assigned only after the Agentverse registration script has run.
  // An API key is used by that script, not by the running Express service.
  return Boolean(agentUri())
}

// Human-facing identity block for the /status endpoint and registration
// metadata. Never includes the seed phrase or any credential.
function identitySummary() {
  return {
    name: AGENT_NAME,
    description: AGENT_DESCRIPTION,
    uri: agentUri(),
    externalEndpoint: env.agentExternalEndpoint || '',
    capabilities: CAPABILITIES,
    keywords: KEYWORDS,
    registered: isConfigured(),
  }
}

module.exports = {
  AGENT_NAME,
  AGENT_DESCRIPTION,
  CAPABILITIES,
  KEYWORDS,
  agentUri,
  isConfigured,
  identitySummary,
}
